package com.hbm.satellite.cargo;
import com.hbm.multiblock.DummyableBlock;import com.mojang.serialization.MapCodec;import net.minecraft.core.BlockPos;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.SoundType;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.BlockState;
/** Original3x1x3 cargo pad, offset1, all8 real inventory proxy hosts placed atomically. */
public final class SatelliteDockBlock extends DummyableBlock {
 public SatelliteDockBlock(){super(Properties.of().strength(5,6).sound(SoundType.STONE).requiresCorrectToolForDrops().noOcclusion());}@Override protected MapCodec<? extends DummyableBlock> codec(){return MapCodec.unit(this);}@Override public int[] dimensions(){return new int[]{0,0,1,1,1,1};}@Override public int offset(){return 1;}
 @Override public void setPlacedBy(Level level,BlockPos pos,BlockState state,LivingEntity entity,ItemStack stack){super.setPlacedBy(level,pos,state,entity,stack);if(!level.isClientSide){var core=findCore(level,pos);if(core==null)return;for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)if(x!=0||z!=0)setPort(level,core.offset(x,0,z),true);var name=stack.get(net.minecraft.core.component.DataComponents.CUSTOM_NAME);if(name!=null&&level.getBlockEntity(core) instanceof SatelliteDockBlockEntity dock)dock.setCustomName(name);}}
 @Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return isCore(state)?new SatelliteDockBlockEntity(pos,state):isPort(state)?new SatelliteDockPort(pos,state):null;}@Override public <T extends BlockEntity>BlockEntityTicker<T> getTicker(Level level,BlockState state,BlockEntityType<T> type){return level.isClientSide||!isCore(state)?null:createTickerHelper(type,SatelliteCargoContent.ENTITY.get(),(world,pos,current,dock)->dock.tick());}
}
